{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Octreotide, a cyclic octapeptide, had an absolute oral bioavailability of only 0.6 ± 0.4% in healthy volunteers after an 8 mg capsule, demonstrating that peptide drugs of this class are very poorly absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Plecanatide, a peptide, exhibited negligible systemic availability after oral administration, with plasma concentrations below the limit of quantitation after a 3 mg oral dose, supporting very low oral bioavailability for peptide-based drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "CGP 38 560, a peptidomimetic renin inhibitor, had oral bioavailability below 1% in humans at a 200 mg oral dose, supporting low F for peptide-like molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "CDP323 showed 14% absolute oral bioavailability compared with intravenous dosing in humans, still below the 20% threshold, indicating that even a relatively better-absorbed analog does not reach high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Aliskiren, a small-molecule renin inhibitor, had a mean absolute oral bioavailability of 2.6% in healthy male subjects, supporting that renin/peptide-related inhibitors generally have low oral F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a large acylated/PEGylated peptide with many amide bonds, closely analogous to peptide drugs such as octreotide and plecanatide, which have very low oral bioavailability. All relevant experimental analogs show F below 20%, mostly below 7%, and none support high oral bioavailability. Therefore the query is predicted to have low absolute oral bioavailability at the F >= 20% threshold.",
  "evidence_gaps": [
    "No direct human absolute oral bioavailability measurement for the exact query molecule is present in the provided records.",
    "The fasted-state condition is specified, but no direct fasted-state F data for the query is available; oral peptide absorption is generally low and often requires absorption enhancers."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

